// Loads the pixel-art block icons (generated by ui/web3d/tools/gen_icons.py,
// saved as real PNGs under /icons/) as three.js textures. The scene no
// longer draws any art itself -- every material's `map` traces back to a
// file here, so what a block looks like can be checked by opening the PNG
// directly instead of reasoning about canvas-drawing code.
import * as THREE from 'three';

const ICON_NAMES = [
  'grass', 'dirt', 'dirt_mining', 'paddy', 'paddy_crop', 'thatch',
  'stone', 'stone_brick', 'planks',
  'brick', 'glass', 'leaves', 'log', 'gravel', 'road', 'sidewalk', 'concrete',
  'metal', 'warning', 'roof', 'roof_shingle', 'window_lit',
];
const WALL_STYLES = ['glass', 'brick', 'stone', 'metal', 'planks', 'panel'];
const WALL_VARIANTS_PER_STYLE = 4;

const loader = new THREE.TextureLoader();
function loadIcon(name) {
  return new Promise((resolve, reject) => {
    loader.load(
      `/icons/${name}.png`,
      (tex) => {
        // magFilter stays Nearest for the crisp pixel-art look up close;
        // minFilter needs mipmaps or a texture repeated 50-100x across a
        // big wall aliases into solid noise once minified (nearest-
        // sampling a highly repeated pattern with no mip chain).
        // NearestMipmapLinear keeps each mip level blocky while blending
        // smoothly between levels at a distance.
        tex.magFilter = THREE.NearestFilter;
        tex.minFilter = THREE.NearestMipmapLinearFilter;
        tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
        tex.colorSpace = THREE.SRGBColorSpace;
        resolve(tex);
      },
      undefined,
      reject,
    );
  });
}

export const TEX = {};
export const WALL = {}; // style -> [tex, tex, tex, tex]

export async function loadAllTextures() {
  const base = await Promise.all(ICON_NAMES.map(loadIcon));
  ICON_NAMES.forEach((name, i) => { TEX[name] = base[i]; });

  for (const style of WALL_STYLES) {
    const variants = await Promise.all(
      Array.from({ length: WALL_VARIANTS_PER_STYLE }, (_, i) => loadIcon(`wall_${style}_${i}`))
    );
    WALL[style] = variants;
  }
  return TEX;
}

export function pickWallVariant(style, rng) {
  const variants = WALL[style] || WALL.stone;
  return variants[(rng() * variants.length) | 0];
}
